import type { AgentManifest } from '@tessera/compiler'

/** The first line of a generated file. `tessera agent-files` rewrites a file only if it starts with this, or with `--force`. */
export const GENERATED_MARKER =
  '<!-- Generated by `tessera agent-files`. Edit tessera.config.ts or the components, not this file. -->'

const list = (items: string[]) => items.map((i) => `- ${i}`).join('\n')

function componentLine(c: AgentManifest['components'][number]): string {
  const variants = c.variants.map((v) => `${v.name}: ${v.values.join(' | ')}`).join('; ')
  const events = Object.keys(c.events)
    .map((e) => `@${e}`)
    .join(', ')
  const parts = [
    c.description,
    variants && `variants ${variants}`,
    events && `events ${events}`,
    c.deprecated !== undefined ? `deprecated${c.deprecated ? `: ${c.deprecated}` : ''}` : '',
  ].filter(Boolean)
  return `\`${c.name}\`${parts.length ? ` — ${parts.join('. ')}` : ''}`
}

/** The APIs of the project, if it has any: what a call may use, and the tool that gives the details. */
function apisSection(manifest: AgentManifest, ticks: boolean): string {
  if (!manifest.apis.length) return ''
  const name = (n: string) => (ticks ? `\`${n}\`` : n)
  const lines = manifest.apis.map((a) => {
    const endpoints = a.endpoints.map((e) => `${e.method} ${e.path}`).join(', ')
    return `${name(a.name)}: ${endpoints || 'no description, so calls are not checked'}`
  })
  const how = ticks
    ? `\nCall them as \`<name>.get('/path')\`, \`<name>.post('/path')\` and so on (plain \`get\` is the \`default\` API). A call on an API that has a description is checked by the compiler; \`get_endpoint\` in \`npx tessera mcp\` gives an endpoint's parameters and answer.\n`
    : ''
  return `\n## APIs\n\n${list(lines)}\n${how}`
}

/** The shared state of the project, if it has any: what a component may use, and how it may change it. */
function stateSection(manifest: AgentManifest, ticks: boolean): string {
  if (!manifest.state.length) return ''
  const name = (n: string) => (ticks ? `\`${n}\`` : n)
  const lines = manifest.state.map(
    (s) =>
      `${name(s.name)}: ${s.members.map((m) => (m.kind === 'function' ? `${m.name}()` : m.name)).join(', ') || 'nothing exported'}`,
  )
  const how = ticks
    ? `\nName a piece of state in a template or a script, with no import: \`{cart.count}\`, \`cart.add(item)\`. It is read-only outside its file: change it by calling the functions of its file, never by assigning (\`cart.items = []\` is an error). Put server data in \`get\`, not in state. \`get_state\` in \`npx tessera mcp\` gives the members.\n`
    : ''
  return `\n## Shared state\n\n${list(lines)}\n${how}`
}

/** AGENTS.md: the rules an AI coding tool must follow in this project, and where the facts are. */
export function agentsMd(manifest: AgentManifest): string {
  const governed = Object.keys(manifest.rules.governed)
  const themes = manifest.tokens.themes.map((t) => t.name)
  return `${GENERATED_MARKER}
# Working in this project

This is a Tessera project. The compiler rejects UI that is off the design system, so build from what exists
and check your work.

## Rules

- Use the components below. Do not invent a component, and do not use a variant, slot or event a component does not declare.
- In \`<style>\`, write design tokens (\`$space.4\`, \`$color.surface.default\`), never raw values. These properties must use tokens: ${governed.join(', ') || '(none configured)'}.
- Prefer semantic tokens (\`color.text.default\`) to primitive ones (\`color.blue.600\`): semantic tokens change with the theme${themes.length ? ` (${themes.join(', ')})` : ''}.
- Style only the parts a component's contract documents. Text must keep a contrast ratio of at least ${manifest.rules.contrastMinimum}.
- Pages live in \`app/pages\`, a page may choose a layout (${manifest.routes.layouts.join(', ') || 'none'}), and links use \`<Link to="/path">\` with a route that exists.

## Check your work

Run \`npx tessera check\` after every change. It prints the same errors the build does, each with a fix. \`npx tessera explain <code>\` explains one.
\`npx tessera check --fix\` applies the fixes that cannot change how the page looks.

## Where the facts are

- \`.tessera/manifest.json\`: every component's contract, every token with its value in every theme, and the routes. Read it instead of guessing.
- \`npx tessera mcp\`: a read-only MCP server for the same facts: search components, get a contract, resolve a raw value to a token, and validate a snippet.

## Components

${list(manifest.components.map(componentLine))}
${apisSection(manifest, true)}${stateSection(manifest, true)}`
}

/** llms.txt: the same facts as a short index for language models, in the llms.txt convention. */
export function llmsTxt(manifest: AgentManifest, name = 'This project'): string {
  return `# ${name}

> A Tessera project: components with contracts and design tokens, checked by the compiler. Build from the components and tokens listed in the manifest, and run \`npx tessera check\`.

## Facts

- [Manifest](.tessera/manifest.json): components, tokens (per theme), routes and rules, as JSON
- [Agent rules](AGENTS.md): what to do and not do in this project

## Components

${list(manifest.components.map((c) => `${c.name}: ${c.description ?? c.role}. Usage: \`${c.usage[0]}\``))}

## Routes

${list(manifest.routes.routes.map((r) => `${r.path} (${r.file})`)) || '- (none)'}
${apisSection(manifest, false)}${stateSection(manifest, false)}`
}
